import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  AccessibilityInfo,
  PanResponder,
  View,
  type ViewStyle,
} from "react-native";
import {
  AlphaType,
  Canvas,
  ColorType,
  FilterMode,
  Group,
  MipmapMode,
  Rect,
  Skia,
  TileMode,
  type SkImage,
  type SkPaint,
  type SkRuntimeEffect,
  type SkShader,
} from "@shopify/react-native-skia";
import {
  FOG_DEFAULTS,
  applyWipe,
  createFog,
  packFrame,
  stepFogFixed,
  type FogConfig,
  type FogState,
} from "./fogMath";

export type FoggedGlassProps = {
  /** The scene behind the glass, sharp. */
  image: SkImage;
  /** The same scene, blurred (the foggy read). */
  blurred: SkImage;
  /** Pane size in layout points. */
  width?: number;
  height?: number;
  /** Fog texture resolution. */
  cols?: number;
  rows?: number;
  /** Runs the condensation clock about four times slower. Ignored while Reduce Motion is on. */
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Fired with 'wipe' and 'release' as the glass is wiped (hook haptics here). */
  onFeedback?: (event: "wipe" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

const SKSL = `
uniform shader sceneSharp;
uniform shader sceneBlur;
uniform shader fogTex;
uniform float2 dstOrigin;
uniform float2 dstSize;
uniform float2 texSize;
uniform float2 sceneSize;
uniform float2 blurSize;

half4 main(float2 xy) {
  float2 uv = (xy - dstOrigin) / dstSize;
  float2 tuv = uv * texSize;
  float4 f = fogTex.eval(tuv);
  float fog = clamp(f.r, 0.0, 1.0);
  float dome = f.g;
  half3 sharp = sceneSharp.eval(uv * sceneSize).rgb;
  half3 soft = sceneBlur.eval(uv * blurSize).rgb;
  half3 col = mix(sharp, soft, fog);
  col = mix(col, half3(0.93, 0.95, 0.97), fog * 0.55);
  col *= 1.0 - 0.08 * fog * uv.y;
  if (dome > 0.004) {
    float2 e = 1.0 / texSize;
    float gx = fogTex.eval(tuv + float2(e.x, 0.0)).g - fogTex.eval(tuv - float2(e.x, 0.0)).g;
    float gy = fogTex.eval(tuv + float2(0.0, e.y)).g - fogTex.eval(tuv - float2(0.0, e.y)).g;
    // Lens: the dome bends the view toward the bead centre and magnifies it.
    float2 off = clamp(float2(gx, gy) * 0.24 * dome, -0.05, 0.05);
    half3 bead = sceneSharp.eval(clamp(uv + off, 0.0, 1.0) * sceneSize).rgb;
    // Light from the upper left: bright rim there, contact shadow lower right.
    float lit = clamp((gx * 0.55 + gy * 0.83) * 2.8, -1.0, 1.0);
    float hi = max(lit, 0.0);
    float shadow = max(-lit, 0.0);
    // Small beads stay glassy; the strong shading grows in with size.
    float body = smoothstep(0.05, 0.45, dome);
    float spec = hi * hi * dome * 1.1;
    half3 bcol = bead * (1.04 + 0.26 * hi * body - 0.4 * shadow * body) + spec * body;
    col = mix(col, bcol, smoothstep(0.004, 0.08, dome));
  }
  return half4(col, 1.0);
}
`;

// Compiled once per app lifetime; null means SkSL unsupported -> static fallback.
let cachedEffect: SkRuntimeEffect | null | undefined;
function getEffect(): SkRuntimeEffect | null {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

export function FoggedGlass({
  image,
  blurred,
  width = 340,
  height = 460,
  cols = 96,
  rows = 128,
  slowMotion = false,
  reducedMotion,
  onFeedback,
  label = "Fogged glass window",
  style,
}: FoggedGlassProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;

  const cfg: FogConfig = useMemo(() => ({ cols, rows, width, height }), [cols, rows, width, height]);
  const opts = useMemo(() => FOG_DEFAULTS, []);
  const simRef = useRef<FogState | null>(null);
  if (!simRef.current) simRef.current = createFog(cfg, opts);
  const bytesRef = useRef<Uint8Array | null>(null);
  if (!bytesRef.current) bytesRef.current = new Uint8Array(cols * rows * 4);

  const effect = getEffect();
  const shaders = useMemo(() => {
    if (!effect) return null;
    const sampling = [TileMode.Clamp, TileMode.Clamp, FilterMode.Linear, MipmapMode.None] as const;
    const sharp = image.makeShaderOptions(...sampling);
    const soft = blurred.makeShaderOptions(...sampling);
    return { sharp, soft };
  }, [effect, image, blurred]);
  useEffect(() => () => {
    shaders?.sharp.dispose();
    shaders?.soft.dispose();
  }, [shaders]);

  const [paint, setPaint] = useState<SkPaint | null>(null);
  const latest = useRef({ slowMotion, reduce, onFeedback });
  latest.current = { slowMotion, reduce, onFeedback };

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  // A size or grid change rebuilds the fog from a fully misted pane.
  useEffect(() => {
    simRef.current = createFog(cfg, opts);
    bytesRef.current = new Uint8Array(cfg.cols * cfg.rows * 4);
  }, [cfg, opts]);

  const pointer = useRef({ x: 0, y: 0, active: false });

  // JS-thread frame loop: steps the sim, packs the fog texture and publishes
  // a fresh runtime-shader paint. The per-frame Fabric commits keep the
  // render pipeline awake on a quiet Android screen, the same mechanism as
  // Light on Painting, so no separate keep-alive view is needed.
  useEffect(() => {
    if (!effect || !shaders) return;
    let alive = true;
    let last = 0;
    let prevImage: SkImage | null = null;
    let prevFogShader: SkShader | null = null;
    let prevPaint: SkPaint | null = null;
    const loop = (now: number) => {
      if (!alive) return;
      const sim = simRef.current!;
      const dt = last ? Math.min(48, now - last) / 1000 : 1 / 60;
      last = now;
      if (!latest.current.reduce) {
        stepFogFixed(sim, cfg, dt * (latest.current.slowMotion ? 0.25 : 1), opts);
      }
      const bytes = packFrame(sim, cfg, bytesRef.current!);
      const fogImage = Skia.Image.MakeImage(
        { width: cfg.cols, height: cfg.rows, colorType: ColorType.RGBA_8888, alphaType: AlphaType.Unpremul },
        Skia.Data.fromBytes(bytes),
        cfg.cols * 4,
      );
      if (fogImage) {
        const fogShader = fogImage.makeShaderOptions(TileMode.Clamp, TileMode.Clamp, FilterMode.Linear, MipmapMode.None);
        const next = Skia.Paint();
        next.setShader(
          effect.makeShaderWithChildren(
            [0, 0, cfg.width, cfg.height, cfg.cols, cfg.rows, image.width(), image.height(), blurred.width(), blurred.height()],
            [shaders.sharp, shaders.soft, fogShader],
          ),
        );
        setPaint(next);
        prevPaint?.dispose();
        prevFogShader?.dispose();
        prevImage?.dispose();
        prevPaint = next;
        prevFogShader = fogShader;
        prevImage = fogImage;
      }
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      prevPaint?.dispose();
      prevFogShader?.dispose();
      prevImage?.dispose();
    };
  }, [effect, shaders, cfg, opts, image, blurred]);

  const pan = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          pointer.current = { x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY, active: true };
          const sim = simRef.current;
          if (sim) {
            sim.wasWiping = 0;
            applyWipe(sim, cfg, pointer.current.x, pointer.current.y, opts);
          }
          latest.current.onFeedback?.("wipe");
        },
        onPanResponderMove: (evt) => {
          pointer.current = { x: evt.nativeEvent.locationX, y: evt.nativeEvent.locationY, active: true };
          const sim = simRef.current;
          if (sim) applyWipe(sim, cfg, pointer.current.x, pointer.current.y, opts);
        },
        onPanResponderRelease: () => {
          pointer.current = { x: 0, y: 0, active: false };
          const sim = simRef.current;
          if (sim) sim.wasWiping = 0;
          latest.current.onFeedback?.("release");
        },
        onPanResponderTerminate: () => {
          pointer.current = { x: 0, y: 0, active: false };
          const sim = simRef.current;
          if (sim) sim.wasWiping = 0;
        },
        onPanResponderTerminationRequest: () => false,
      }),
    [cfg, opts],
  );

  return (
    <View
      style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#131828" }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      <Canvas pointerEvents="none" style={{ width, height }}>
        <Group>
          {paint ? (
            <Rect x={0} y={0} width={width} height={height} paint={paint} />
          ) : (
            <Rect x={0} y={0} width={width} height={height} color="#dfe5ea" />
          )}
        </Group>
      </Canvas>
    </View>
  );
}

// Pure condensation physics for Fogged Glass. A pane mists over; a finger
// wipes clear streaks, water beads nucleate, grow by absorbing fog and by
// swallowing each other, and run down the glass with stick-slip, leaving
// wet trails that slowly fog over again. The pane is a grid of fog cells
// plus a small set of droplets; every function is a worklet so the sim can
// run on either thread, and plain JS (tests, web preview) ignores the tag.
// No Math.random anywhere: a seeded generator keeps web, native and tests
// in agreement frame for frame.

export type FogPointer = { x: number; y: number; active: number };

export type FogConfig = {
  cols: number;
  rows: number;
  /** Pane size in px. */
  width: number;
  height: number;
};

/** Per-drop stride: x, y, r, mode (0 empty, 1 stuck, 2 sliding), vel, pin. */
export const STRIDE = 6;

export type FogState = {
  /** Fog per cell, 0 (clear) .. 1 (opaque), row-major. */
  fog: Float32Array;
  /** Droplet slots, STRIDE floats each. */
  drops: Float32Array;
  dropCount: number;
  /** Seeded PRNG state. */
  seed: number;
  /** Sim clock, seconds. */
  time: number;
  /** Nucleation accumulator. */
  acc: number;
  /** Water squeezed out by wiping, not yet shed as beads. */
  squeeze: number;
  /** Previous wipe point, for capsule strokes. */
  wasWiping: number;
  lastX: number;
  lastY: number;
};

export const FOG_DEFAULTS = {
  /** Starting and resting fog level. */
  fogStart: 0.96,
  fogMax: 0.97,
  /** Fraction of the gap to fogMax closed per second, before per-cell noise. */
  regrowRate: 0.045,
  /** Wipe brush radius, px. */
  wipeRadius: 30,
  /** Seconds between ambient bead nucleation attempts. */
  nucleationInterval: 0.45,
  /** Beads at or below this radius never slide, px. */
  stickRadius: 3.2,
  /** Slide speed scale, px/s. */
  slideSpeed: 130,
  /** Top slide speed, px/s. */
  maxSpeed: 210,
  /** Sideways wobble of a running bead, px. */
  wobble: 2.4,
  /** Radius a sliding bead sheds per second, px/s. */
  shedRate: 0.4,
  /** Growth of a bead from fog it absorbs, px radius per (fog * px traveled / diameter). */
  absorb: 0.85,
  /** Growth of a stuck bead from surrounding condensation, px/s at fog 1. */
  condense: 0.085,
  /** Largest bead radius, px. */
  maxRadius: 13,
  /** Fog a drip trail keeps (a wet streak) before it creeps back, of the local fog. */
  trailResidual: 0.16,
  /** Chance a sliding bead leaves a micro droplet, per px traveled. */
  microShed: 0.012,
  /** Fixed timestep ceiling for the sim. */
  fixedDt: 1 / 120,
};

export type FogOptions = typeof FOG_DEFAULTS;

export function cellCount(cfg: FogConfig): number {
  'worklet';
  return cfg.cols * cfg.rows;
}

/** Deterministic per-cell noise in [0, 1). */
export function hash01(i: number, salt: number): number {
  'worklet';
  let h = (Math.imul(i, 374761393) + Math.imul(salt, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Seeded generator; advances state.seed. */
export function rand(state: FogState): number {
  'worklet';
  state.seed = (state.seed + 0x6d2b79f5) | 0;
  let t = state.seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

export function createFog(cfg: FogConfig, opts: FogOptions): FogState {
  'worklet';
  const n = cellCount(cfg);
  const fog = new Float32Array(n);
  for (let i = 0; i < n; i++) fog[i] = opts.fogStart * (0.94 + 0.12 * hash01(i, 5));
  return {
    fog,
    drops: new Float32Array(96 * STRIDE),
    dropCount: 0,
    seed: 20260618,
    time: 0,
    acc: 0,
    squeeze: 0,
    wasWiping: 0,
    lastX: 0,
    lastY: 0,
  };
}

const MAX_DROPS = 96;

export function maxDrops(): number {
  'worklet';
  return MAX_DROPS;
}

export function fogAt(state: FogState, cfg: FogConfig, x: number, y: number): number {
  'worklet';
  const c = Math.max(0, Math.min(cfg.cols - 1, Math.floor((x / cfg.width) * cfg.cols)));
  const r = Math.max(0, Math.min(cfg.rows - 1, Math.floor((y / cfg.height) * cfg.rows)));
  return state.fog[r * cfg.cols + c];
}

function spawnDrop(state: FogState, cfg: FogConfig, x: number, y: number, r: number): number {
  'worklet';
  if (state.dropCount >= MAX_DROPS) return -1;
  for (let s = 0; s < MAX_DROPS; s++) {
    const k = s * STRIDE;
    if (state.drops[k + 3] !== 0) continue;
    state.drops[k] = Math.max(r, Math.min(cfg.width - r, x));
    state.drops[k + 1] = Math.max(r, Math.min(cfg.height - r, y));
    state.drops[k + 2] = r;
    state.drops[k + 3] = 1;
    state.drops[k + 4] = 0;
    state.drops[k + 5] = 0.8 + rand(state) * 0.5;
    state.dropCount++;
    return s;
  }
  return -1;
}

function removeDrop(state: FogState, slot: number): void {
  'worklet';
  state.drops[slot * STRIDE + 3] = 0;
  state.dropCount--;
}

/**
 * Clear fog along the segment (x0,y0)-(x1,y1) with a soft circular brush.
 * residual keeps a fraction of the local fog (a wet streak that creeps
 * back). Returns the average fog removed across touched cells (0..1).
 */
export function clearBand(
  state: FogState,
  cfg: FogConfig,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  radius: number,
  residual = 0,
): number {
  'worklet';
  const cw = cfg.width / cfg.cols;
  const ch = cfg.height / cfg.rows;
  const minX = Math.max(0, Math.floor((Math.min(x0, x1) - radius) / cw));
  const maxX = Math.min(cfg.cols - 1, Math.floor((Math.max(x0, x1) + radius) / cw));
  const minY = Math.max(0, Math.floor((Math.min(y0, y1) - radius) / ch));
  const maxY = Math.min(cfg.rows - 1, Math.floor((Math.max(y0, y1) + radius) / ch));
  const dx = x1 - x0;
  const dy = y1 - y0;
  const len2 = dx * dx + dy * dy;
  const r2 = radius * radius;
  let removed = 0;
  let touched = 0;
  for (let row = minY; row <= maxY; row++) {
    for (let col = minX; col <= maxX; col++) {
      const px = (col + 0.5) * cw;
      const py = (row + 0.5) * ch;
      let t = len2 > 0 ? ((px - x0) * dx + (py - y0) * dy) / len2 : 0;
      t = Math.max(0, Math.min(1, t));
      const qx = px - (x0 + t * dx);
      const qy = py - (y0 + t * dy);
      const d2 = qx * qx + qy * qy;
      if (d2 > r2) continue;
      const f = 1 - Math.sqrt(d2) / radius;
      const soft = f <= 0 ? 0 : f >= 0.55 ? 1 : f / 0.55;
      const i = row * cfg.cols + col;
      const before = state.fog[i];
      const after = Math.max(before * residual, before - soft);
      state.fog[i] = after;
      removed += before - after;
      touched++;
    }
  }
  return touched > 0 ? removed / touched : 0;
}

function nucleate(state: FogState, cfg: FogConfig, opts: FogOptions): void {
  'worklet';
  for (let attempt = 0; attempt < 3; attempt++) {
    const x = rand(state) * cfg.width;
    const y = rand(state) * cfg.height * 0.92;
    if (fogAt(state, cfg, x, y) < 0.8) continue;
    if (rand(state) < 0.55) {
      spawnDrop(state, cfg, x, y, 0.9 + rand(state) * 1.8);
      return;
    }
  }
}

/** Finger wipe: capsule clear along the stroke, plus beads squeezed out at the rim. */
export function applyWipe(state: FogState, cfg: FogConfig, x: number, y: number, opts: FogOptions): void {
  'worklet';
  const x0 = state.wasWiping ? state.lastX : x;
  const y0 = state.wasWiping ? state.lastY : y;
  const cleared = clearBand(state, cfg, x0, y0, x, y, opts.wipeRadius);
  state.lastX = x;
  state.lastY = y;
  state.wasWiping = 1;
  // Cleared water gathers until there is enough for a rim bead.
  state.squeeze += cleared;
  if (cleared > 0.1 && state.squeeze > 0.8) {
    state.squeeze -= 0.8;
    const t = rand(state);
    const side = rand(state) < 0.5 ? -1 : 1;
    const dx = x - x0;
    const dy = y - y0;
    const len = Math.sqrt(dx * dx + dy * dy) || 1;
    const px = (-dy / len) * side * opts.wipeRadius * (0.75 + 0.35 * rand(state));
    const py = (dx / len) * side * opts.wipeRadius * (0.75 + 0.35 * rand(state));
    spawnDrop(state, cfg, x0 + dx * t + px, y0 + dy * t + py, 1.6 + rand(state) * 2.4);
  }
}

/** Merge any two drops whose domes touch; the bigger one keeps its slot. */
function mergeTouching(state: FogState, opts: FogOptions): void {
  'worklet';
  for (let a = 0; a < MAX_DROPS; a++) {
    const ka = a * STRIDE;
    if (state.drops[ka + 3] === 0) continue;
    const ra = state.drops[ka + 2];
    for (let b = a + 1; b < MAX_DROPS; b++) {
      const kb = b * STRIDE;
      if (state.drops[kb + 3] === 0) continue;
      const rb = state.drops[kb + 2];
      const dx = state.drops[kb] - state.drops[ka];
      const dy = state.drops[kb + 1] - state.drops[ka + 1];
      const rr = (ra + rb) * 0.68;
      if (dx * dx + dy * dy >= rr * rr) continue;
      const big = ra >= rb ? ka : kb;
      const small = ra >= rb ? kb : ka;
      const rs = state.drops[small + 2];
      const rb2 = state.drops[big + 2];
      const wa = rb2 * rb2;
      const wb = rs * rs;
      state.drops[big] = (state.drops[big] * wa + state.drops[small] * wb) / (wa + wb);
      state.drops[big + 1] = (state.drops[big + 1] * wa + state.drops[small + 1] * wb) / (wa + wb);
      state.drops[big + 2] = Math.min(opts.maxRadius, Math.sqrt(wa + wb));
      if (state.drops[small + 4] > state.drops[big + 4]) state.drops[big + 4] = state.drops[small + 4];
      removeDrop(state, small === ka ? a : b);
      if (small === ka) break;
    }
  }
}

/** One fixed substep: regrowth, condensation, droplet stick-slip, merging. */
export function stepFog(state: FogState, cfg: FogConfig, dt: number, opts: FogOptions): void {
  'worklet';
  state.time += dt;
  const fog = state.fog;
  const n = cellCount(cfg);
  for (let i = 0; i < n; i++) {
    const target = opts.fogMax * (0.86 + 0.14 * hash01(i, 11));
    fog[i] += (target - fog[i]) * opts.regrowRate * dt;
  }

  state.acc += dt;
  while (state.acc >= opts.nucleationInterval) {
    state.acc -= opts.nucleationInterval;
    nucleate(state, cfg, opts);
  }

  for (let s = 0; s < MAX_DROPS; s++) {
    const k = s * STRIDE;
    let mode = state.drops[k + 3];
    if (mode === 0) continue;
    let x = state.drops[k];
    let y = state.drops[k + 1];
    let r = state.drops[k + 2];
    let vel = state.drops[k + 4];
    const pin = state.drops[k + 5];

    if (mode === 1) {
      // Pinned bead: drink the condensation around it until gravity wins.
      const local = fogAt(state, cfg, x, y);
      r = Math.min(opts.maxRadius, r + opts.condense * local * dt);
      if (r > opts.stickRadius * (1.25 + 0.55 * pin)) {
        mode = 2;
        vel = 24 + 30 * pin;
      } else {
        state.drops[k + 2] = r;
        continue;
      }
    }

    // Sliding bead: speed chases a size-based target, pulsing so the run
    // jerks between slips and near-stops.
    const target = Math.max(
      14,
      Math.min(opts.maxSpeed, (opts.slideSpeed * (r - opts.stickRadius * 0.7)) / opts.stickRadius),
    );
    const pulse = 0.55 + 0.65 * Math.max(0, Math.sin(state.time * (5.5 + 3.5 * pin) + s * 2.7));
    vel += (target * pulse - vel) * Math.min(1, 9 * dt);
    const dy = vel * dt;
    const wob = Math.sin(state.time * 11 + s * 2.7) * opts.wobble * Math.min(1, vel / 60) * dt;
    x += wob;
    if (x < r) x = r;
    if (x > cfg.width - r) x = cfg.width - r;
    const yNext = y + dy;

    // Drink the fog on the path, leave a wet streak, shed a little water.
    const bandFog = sampleBand(state, cfg, x, y, x, yNext, r * 0.8);
    clearBand(state, cfg, x, y, x, yNext, r * 0.62, opts.trailResidual);
    r += (opts.absorb * bandFog * dy) / (2 * r);
    r -= opts.shedRate * (0.5 + vel / 160) * dt;

    // A fast, big bead leaves micro droplets behind in its trail.
    if (r > opts.stickRadius * 1.15 && vel > 70 && state.dropCount < 80 && rand(state) < dy * opts.microShed) {
      spawnDrop(state, cfg, x + (rand(state) - 0.5) * r, y - r * (0.9 + rand(state) * 0.5), 0.6 + rand(state) * 0.7);
    }

    if (r > opts.maxRadius) r = opts.maxRadius;
    y = yNext;
    if (y - r > cfg.height) {
      removeDrop(state, s);
      continue;
    }
    // Shed enough water and the bead pins again: stick after slip.
    if (r < opts.stickRadius * (0.72 + 0.34 * pin)) {
      mode = 1;
      vel = 0;
      if (r < 0.8) {
        removeDrop(state, s);
        continue;
      }
    }
    state.drops[k] = x;
    state.drops[k + 1] = y;
    state.drops[k + 2] = r;
    state.drops[k + 3] = mode;
    state.drops[k + 4] = vel;
  }

  mergeTouching(state, opts);
}

/** Average fog along a band without changing it. */
export function sampleBand(
  state: FogState,
  cfg: FogConfig,
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  radius: number,
): number {
  'worklet';
  const cw = cfg.width / cfg.cols;
  const ch = cfg.height / cfg.rows;
  const minX = Math.max(0, Math.floor((Math.min(x0, x1) - radius) / cw));
  const maxX = Math.min(cfg.cols - 1, Math.floor((Math.max(x0, x1) + radius) / cw));
  const minY = Math.max(0, Math.floor((Math.min(y0, y1) - radius) / ch));
  const maxY = Math.min(cfg.rows - 1, Math.floor((Math.max(y0, y1) + radius) / ch));
  let sum = 0;
  let touched = 0;
  for (let row = minY; row <= maxY; row++) {
    for (let col = minX; col <= maxX; col++) {
      const px = (col + 0.5) * cw;
      const py = (row + 0.5) * ch;
      const ddx = px - x0;
      const ddy = py - y0;
      if (ddx * ddx + ddy * ddy > radius * radius) continue;
      sum += state.fog[row * cfg.cols + col];
      touched++;
    }
  }
  return touched > 0 ? sum / touched : 0;
}

/** Advance by a wall-clock frame delta using capped substeps. */
export function stepFogFixed(state: FogState, cfg: FogConfig, frameDt: number, opts: FogOptions): void {
  'worklet';
  let remaining = Math.min(frameDt, 0.1);
  while (remaining > 1e-6) {
    const dt = Math.min(opts.fixedDt, remaining);
    stepFog(state, cfg, dt, opts);
    remaining -= dt;
  }
}

/**
 * Pack the current frame into an RGBA byte texture (cols x rows):
 * R and A carry the fog level with per-cell grain (A is for the Canvas2D
 * mask on web), G carries the droplet dome height. Beads clear the fog
 * beneath their dome.
 */
export function packFrame(state: FogState, cfg: FogConfig, bytes: Uint8Array): Uint8Array {
  'worklet';
  const n = cellCount(cfg);
  for (let i = 0; i < n; i++) {
    const grain = 0.8 + 0.45 * hash01(i, 13);
    const f = Math.max(0, Math.min(1, state.fog[i] * grain));
    const a = i * 4;
    const v = Math.round(f * 255);
    bytes[a] = v;
    bytes[a + 1] = 0;
    bytes[a + 2] = 0;
    bytes[a + 3] = v;
  }
  const cw = cfg.width / cfg.cols;
  const ch = cfg.height / cfg.rows;
  for (let s = 0; s < MAX_DROPS; s++) {
    const k = s * STRIDE;
    if (state.drops[k + 3] === 0) continue;
    const x = state.drops[k];
    const y = state.drops[k + 1];
    const r = state.drops[k + 2];
    const minX = Math.max(0, Math.floor((x - r) / cw));
    const maxX = Math.min(cfg.cols - 1, Math.floor((x + r) / cw));
    const minY = Math.max(0, Math.floor((y - r) / ch));
    const maxY = Math.min(cfg.rows - 1, Math.floor((y + r) / ch));
    for (let row = minY; row <= maxY; row++) {
      for (let col = minX; col <= maxX; col++) {
        const px = (col + 0.5) * cw;
        const py = (row + 0.5) * ch;
        const ddx = px - x;
        const ddy = py - y;
        const d2 = (ddx * ddx + ddy * ddy) / (r * r);
        if (d2 > 1) continue;
        const h = Math.sqrt(1 - d2);
        const a = (row * cfg.cols + col) * 4;
        const clear = d2 < 0.55 ? 1 : 1 - (d2 - 0.55) / 0.45;
        bytes[a] = Math.round(bytes[a] * (1 - clear * 0.97));
        bytes[a + 3] = Math.round(bytes[a + 3] * (1 - clear * 0.97));
        const dome = Math.round(h * 255);
        if (dome > bytes[a + 1]) bytes[a + 1] = dome;
      }
    }
  }
  return bytes;
}

/** Total fog across the pane, for settle checks in tests. */
export function totalFog(state: FogState): number {
  'worklet';
  let s = 0;
  for (let i = 0; i < state.fog.length; i++) s += state.fog[i];
  return s;
}

